    private void passwordFieldActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_passwordFieldActionPerformed
        loginButtonActionPerformed(evt);     // Enter في خانة الباسوورد = نفس ضغطة Login
    }//GEN-LAST:event_passwordFieldActionPerformed

    private void signUpLinkActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_signUpLinkActionPerformed
        MainFrame frame = (MainFrame) SwingUtilities.getWindowAncestor(this);   // نجيب النافذة اللي إحنا داخلها
        frame.showScreen("signup", "Sign up");                                  // نعرض شاشة Sign up
    }//GEN-LAST:event_signUpLinkActionPerformed

    private void loginButtonActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_loginButtonActionPerformed
        String username = usernameField.getText();                   // نقرأ اللي في خانة الـ username
        String password = new String(passwordField.getPassword());   // نقرأ الباسوورد

        if (username.isEmpty() || password.isEmpty()) {               // لو وحدة من الخانتين فاضية
            JOptionPane.showMessageDialog(this, "Please fill all fields");   // رسالة تنبيه
        } else {
            // TODO (Server): send login request to server and check username & password
            System.out.println("Login: " + username);                 // مؤقتاً نطبع (بعدين نرسل للسيرفر)
            MainFrame frame = (MainFrame) SwingUtilities.getWindowAncestor(this); // نجيب النافذة الرئيسية اللي إحنا داخلها
            frame.showScreen("hallsList", "Halls list");                              // نعرض شاشة القاعات ونغير عنوان النافذة
        }
    }//GEN-LAST:event_loginButtonActionPerformed


